void operation(int value) {
    if (value < 0) throw std::out_of_range("Value negative");
}

try {
    operation(-1);
} catch (const std::out_of_range& e) {
    std::cerr << "Specific: " << e.what();
} catch (const std::exception& e) {
    std::cerr << "General: " << e.what();
}

class CustomError : public std::exception {
public:
    const char* what() const noexcept override {
        return "Custom hardware failure";
    }
};

void check_hardware() {
    throw CustomError();
}

class FileHandle {
    FILE* fp;
public:
    FileHandle(const char* name) : fp(fopen(name, "r")) {}
    ~FileHandle() { if (fp) fclose(fp); }
};

void process_file() {
    FileHandle h("data.txt");
    if (/* condition */) throw std::bad_function_call();
    // Destructor of FileHandle called automatically (RAII)
}
